BASE='https://www.expressspa.com.au'
MAP='https://maps.google.com/maps?cid=7345401442514349636'
e=html.escape
services=[
dict(slug='spa-relocation-melbourne',name='Spa relocation',title='Spa relocation in Melbourne. Handled properly.',intro='Moving house, changing your backyard or collecting a spa? Get a transport plan built around the spa, the route and the access at both ends.',image='gallery-01',tag='01 / Spa relocation',sections=[('The whole move starts with access','Tell us where your spa is now and where it needs to go. A clear path, the empty spa weight and a few photos help us choose the right equipment and identify anything that needs arranging before delivery day.'),('Collection, transport and placement','We assess loading and unloading separately. A simple pickup can still have a difficult delivery, so we check gates, steps, slopes, fences and the position of the truck before confirming the scope.'),('Know what to arrange before moving','The spa needs to be drained and ready for transport. Any electrical disconnection or reconnection must be arranged with a licensed electrician. Confirm the destination base and any access changes before booking.')],checks=['Pickup and delivery suburbs','Spa dimensions and empty weight, if known','Photos of the spa and both access routes','Preferred move date and any settlement deadline'],faqs=[('Can you move a spa within the same property?','Yes, send photos of its current position and proposed location. Even a short move can need specialist equipment or a lift; we will assess it before quoting.'),('What does a spa relocation quote include?','Your quote sets out the agreed transport, lifting and labour. Let us know about electrical work, preparation or disposal needs so these can be discussed separately.')]),
dict(slug='swim-spa-transport',name='Swim spa transport',title='Big swim spa. Proper transport plan.',intro='Specialist trailer transport for oversized swim spas across Melbourne, Victoria and selected interstate routes by arrangement.',image='hero-trailer',tag='02 / Swim spa transport',sections=[('Dimensions come first','A swim spa needs its own transport assessment. Send the exact length, width, height and empty weight from the manufacturer, along with the model and pickup location. A standard spa quote is not a reliable guide for an oversized load.'),('Plan the final placement','Truck access, overhead clearance and the distance from the unloading position to the final base all affect the lift plan. Photos are a starting point; a site assessment or additional lifting arrangements may be required.'),('Coordinate with your supplier','If the spa is still at the factory or retailer, tell us when it will be ready for collection. We coordinate the agreed pickup, transport and arrival window after the route and delivery method are confirmed.')],checks=['Manufacturer and exact model','Empty weight and full transport dimensions','Factory or retailer collection contact','Destination access and base readiness'],faqs=[('Can you deliver my swim spa over a fence?','Possibly. Suitability depends on the spa weight, lift reach, truck position and site conditions. Send photos and specifications so we can assess the lifting requirements.'),('Do you offer interstate swim spa transport?','Selected routes can be arranged across SA, NSW and Southern Queensland. Availability, timing and equipment are confirmed for each job.')]),
dict(slug='crane-spa-delivery',name='Crane & difficult access',title='A fence in the way? Let’s plan the lift.',intro='Light crane truck delivery for suitable spa lifts, tight access and backyards where the usual approach will not work.',image='services-crane',tag='03 / Crane spa delivery',sections=[('Show us the whole access route','Photograph the street, driveway, gate or fence, and final spa position. Include overhead obstacles, changes in level and any narrow sections. The truck needs a suitable place to operate, not just somewhere to park.'),('Every lift has limits','Spa weight and crane reach work together. We assess the load, operating position and site conditions before confirming whether our equipment is suitable. Larger or more complex lifts may need separate arrangements.'),('A clear plan before delivery day','We discuss any access preparation and responsibilities before booking. Avoid removing fencing or arranging other work until the lifting and placement plan is agreed.')],checks=['Spa model, dimensions and empty weight','Photos from street to final position','Fence height and approximate lift distance','Overhead obstructions and driveway conditions'],faqs=[('Can you guarantee a lift from photos?','Photos help us assess the job, but do not guarantee a lift. We may need measurements, manufacturer specifications or a site assessment before confirming.'),('Is the crane included in every delivery?','Lifting requirements are assessed for each move. Your quote will explain the agreed lifting, truck travel and labour.')]),
dict(slug='second-hand-spa-delivery',name='Second-hand spa delivery',title='Found the spa. Now get it home.',intro='Buying through Facebook Marketplace, Gumtree or a private seller? Check the transport before you commit to collection.',image='gallery-03',tag='04 / Private sale delivery',sections=[('Ask the seller for the right photos','A picture of the spa is not enough. Ask for the access path, gates, steps and street-side loading position. Find the model, dimensions and empty weight where possible, and check when the seller can provide access.'),('Check both properties','Getting the spa out and getting it into your backyard can be very different jobs. Send photos at both ends so the quote covers the whole move and the agreed final position.'),('Keep the sale and the move separate','Transport does not establish the condition or working order of a used spa. Check the spa with the seller and arrange electrical preparation separately. Confirm transport availability before promising a pickup date.')],checks=['Seller suburb and collection availability','Listing link or spa photos','Access photos at both addresses','Spa model and dimensions'],faqs=[('Should I get a transport quote before buying?','Yes. Access and lifting can materially affect the cost and feasibility of a move. Send the listing and access details before committing to a collection deadline.'),('Can you coordinate with the seller?','We can discuss collection arrangements once the move is agreed. Include the pickup constraints in your enquiry; do not share the seller’s private details without their permission.')]),
dict(slug='factory-direct-spa-delivery',name='Factory-direct delivery',title='Factory floor to your backyard.',intro='Coordinate a new spa’s collection, transport and placement with one clear delivery enquiry.',image='gallery-04',tag='05 / Factory-direct delivery',sections=[('Confirm when the spa is ready','Tell us the manufacturer or retailer, spa model and collection location. We need its transport dimensions, empty weight and confirmed release date before agreeing a pickup window.'),('Make the site ready for arrival','The final location needs an appropriate base and agreed access. We assess the delivery route and lifting requirements, while electrical connection and other site works remain separately arranged.'),('For retailers and manufacturers','Arrange individual customer deliveries or talk to us about repeat and overflow transport. Share the proposed service area, typical spa sizes and expected volume so we can discuss a practical booking process.')],checks=['Order reference and collection contact','Manufacturer specifications','Delivery suburb and access photos','Readiness date at the factory and destination'],faqs=[('Do I book through you or the retailer?','Check whether delivery is already included in your purchase. If you are arranging transport separately, send the model, supplier and destination so we can quote the agreed scope.'),('Can retailers arrange regular deliveries?','Yes, ask about retailer delivery support. Route availability, service scope and commercial arrangements are agreed directly; no fixed volume is required to make an enquiry.')])]
areas=[
('melbourne','Melbourne','Metro moves, from collection to final placement.','A Melbourne spa move can be short on kilometres and still need careful access planning. Gates, side paths, overhead lines and the distance from the street to the final base all matter.','Across the metro area','Include both suburbs and any time restrictions for loading. Apartment access, shared driveways and settlement-day deadlines should be raised before a collection window is agreed.','Make access visible','Send a continuous set of photos from the street to the spa, plus the destination path. A tight gate and an over-fence lift are different transport problems, even on the same street.'),
('geelong','Geelong','Spa delivery between Geelong, Melbourne and regional Victoria.','If your spa is coming from a Melbourne retailer or moving between properties around Geelong, the quote needs the complete route as well as access at both ends.','Coordinate the collection','For a new spa, check when the supplier will release it. For a private sale, agree seller availability only after transport has been confirmed.','Coastal and regional destinations','Include the actual destination suburb rather than just Geelong. A move continuing to the Bellarine or Surf Coast can change truck travel and scheduling.'),
('mornington-peninsula','Mornington Peninsula','A delivery plan for your Peninsula spa.','A spa delivery to the Mornington Peninsula starts with the route and the final approach to the property. Sloping drives, narrow entries and a long carry from the truck need to be discussed before booking.','Prepare the property details','Photograph the driveway from the street and show where the spa will sit. Include gate measurements, steps and any height restrictions.','Plan around access windows','If the property is a holiday home or has limited access, tell us when someone can attend. We confirm the collection and delivery arrangements before you organise the rest of the day.'),
('ballarat','Ballarat','New spa delivery and relocations to Ballarat.','Moving a spa from Melbourne to Ballarat, or between local properties? Send the exact suburbs and spa specifications so we can assess the travel, loading and placement.','Make the destination ready','A suitable base and a clear access route should be arranged ahead of delivery. Photos showing any unsealed approach, gradient or restricted driveway help us identify the equipment needed.','Separate preparation from transport','Have the spa drained and electrical preparation organised through the appropriate trades. Your transport quote will set out the agreed delivery and lifting scope.'),
('bendigo','Bendigo','Spa transport to Bendigo and surrounding destinations.','A Bendigo delivery can combine a metropolitan pickup with a regional destination. Exact locations are important: route distance and property access both contribute to the transport plan.','Include the final approach','For properties outside town, describe the driveway surface and where the truck can turn or operate. Send photos rather than assuming a large block means easy access.','Allow time for coordination','Tell us your preferred date and whether it is flexible. Regional availability is confirmed for each enquiry, particularly when collecting from a supplier with fixed opening hours.'),
('gippsland','Gippsland','Spa deliveries along an agreed Gippsland route.','Gippsland covers a large area, so a quote needs the actual pickup and delivery towns. We assess the route, the spa and the access before confirming availability.','Name both towns','A short local relocation and a Melbourne-to-Gippsland delivery have different travel requirements. Add the suburbs or postcodes and any collection deadline to your enquiry.','Check the last part of the trip','Show the driveway, unloading position and final spa base. Remote or constrained access may need additional planning; let us know early about unsealed roads or restricted entry.'),
('regional-victoria','Regional Victoria','A clear plan beyond the metro area.','We assess spa delivery and relocation enquiries throughout regional Victoria. Tell us the full route and how flexible the timing is, then we can discuss the transport arrangements.','Quote the complete journey','Truck travel may include more than the distance between the two properties. The final quote explains the route and billable travel alongside lifting and labour.','Plan for the site','A rural property still needs a suitable operating position and final placement plan. Photos of the approach, overhead clearance, access path and base help us assess the job.'),
('south-australia','South Australia','Selected interstate spa transport by arrangement.','Planning a spa delivery between Victoria and South Australia? Share the exact route, spa specifications and preferred timing. Interstate transport is assessed individually and is subject to suitable scheduling.','Collection and delivery windows','Factory release dates and access at the receiving property need to align. Tell us any restrictions before agreeing a pickup or making commitments to a seller.','Confirm the complete scope','Ask what is included in loading, transport and final placement. An interstate journey does not automatically include every lift or additional site service; these are confirmed in your quote.'),
('new-south-wales','New South Wales','Discuss a Victoria–NSW spa delivery.','Selected spa transport routes between Victoria and New South Wales are available by arrangement. The destination town, spa size and pickup readiness determine what can be scheduled.','Send exact specifications','For swim spas or larger loads, include manufacturer transport dimensions and empty weight. We assess the route and equipment before confirming a transport method.','Prepare both ends','Photos and access restrictions are needed at the pickup and delivery. Let us know about any separate lifting contractor or site works so responsibilities can be agreed beforehand.'),
('southern-queensland','Southern Queensland','Longer-distance spa delivery, planned around your route.','For a spa move between Victoria and Southern Queensland, send the exact towns and preferred timeframe. These are selected interstate arrangements, not a daily scheduled delivery service.','Discuss timing before purchase','A supplier or seller may have a fixed collection window. Confirm transport availability before committing to it, especially when the spa needs specialist lifting.','Build the plan around the load','The spa’s transport dimensions, empty weight, access and final placement all affect the quote. Include clear photos and manufacturer specifications when you make your enquiry.')]
guides=[
('spa-relocation-cost-melbourne','What affects the cost of moving a spa?','Distance, lifting and labour explained before you ask for a quote.',[
('Start with three parts','Express Spa calculates a move around truck kilometres, crane lifting and labour. A short drive can still require a difficult lift, while a longer route with straightforward access may need a different mix of equipment and time. A photo-based assessment helps turn those variables into an agreed quote.'),('Truck kilometres','Share the exact pickup and delivery locations. Ask whether quoted travel includes the truck’s approach and return journey as well as the move between properties. The distance you see in a maps app is not automatically the billable distance.'),('Crane lifts and labour','The spa’s empty weight, crane reach, loading position and access influence the plan. Steps, slopes, narrow paths and preparation can affect the time and crew required. Any lift must be assessed for suitability.'),('What to send for a useful quote','Include both suburbs, the spa model, dimensions, empty weight if known, access photos and preferred timing. Ask about GST, minimum charges and additional services before agreeing the move.')]),
('buying-second-hand-spa-delivery','Buying a second-hand spa? Check the move first.','A practical checklist before arranging collection.',[
('Get the access photos','Ask for photos of the spa, the route out of the property, gates and the truck’s loading position. Take the same photos at your home. Access can affect whether the move is feasible and how much it costs.'),('Find the specifications','The model, dimensions and empty weight help determine equipment and transport. If the seller cannot provide them, photograph the identification plate and share any manufacturer information you have.'),('Confirm condition separately','A transport quote is not a condition report. Check working order with the seller and arrange any professional inspection you need before purchase. A low purchase price does not establish the cost of moving or preparing the spa.'),('Agree collection after transport','Confirm the move date and scope before committing to a seller’s collection deadline. Arrange drainage and licensed electrical disconnection where needed; tell your mover what remains to be done.')]),
('spa-delivery-access-checklist','Will a spa fit? Your delivery access checklist.','The measurements and photos that help plan a safe delivery.',[
('Measure more than the gate','Measure the narrowest points along the complete access route. Include turns, steps, gradients, overhead clearance and the final placement area. The spa may need clearance for handling equipment as well as its own dimensions.'),('Show the truck position','Take photos from the street towards the property. A crane needs an assessed operating position and load plan. Fence height alone does not tell us whether a lift is possible.'),('Check overhead and ground conditions','Show trees, eaves, cables and any soft or uneven ground. Do not remove obstacles or arrange structural changes until the delivery method is agreed. Powerline or lifting concerns require a proper site assessment.'),('Send a simple photo sequence','Send the spa, street approach and access route at both properties. Add approximate measurements and manufacturer specifications. We will tell you if more detail or an assessment is needed.')]),
('prepare-for-spa-relocation','Getting ready for your spa move.','A straightforward checklist for collection and delivery day.',[
('Confirm the agreed scope','Check the date, access, pickup and final placement details on your quote. Tell us if anything changes after assessment, including fences, parked vehicles, landscaping or the spa model.'),('Drain and prepare the spa','Follow the manufacturer’s drainage and preparation instructions. Arrange electrical disconnection and reconnection with a licensed electrician where required. Secure or remove loose accessories as agreed before the move.'),('Prepare the destination','Arrange a suitable base and any separately required site works. Keep the assessed access route available and tell us who will meet the delivery. Do not assume transport includes electrical, fencing or compliance work.'),('Keep the details handy','Have the pickup contact, destination contact and order reference available. If the spa is not ready for collection or access changes, contact us before the truck is dispatched.')])]

def img(name,alt,cls='',eager=False):return f'<img class="{cls}" src="/images/{name}.webp" alt="{e(alt)}" width="1000" height="750" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'
def cards(items):return '<div class="cards">'+''.join(f'<a class="card" href="/{s["slug"]}">{img(s["image"],s["name"])}<div class="card-body"><span class="eyebrow">{s["tag"]}</span><h3>{s["name"]}<span aria-hidden="true">↗</span></h3><p>{s["intro"]}</p></div></a>' for s in items)+'</div>'
def faqs(items):return '<div class="faqs">'+''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in items)+'</div>'
def review_block():return f'''<section class="section reviews"><div class="wrap"><div class="section-head"><div><p class="eyebrow">From the people we’ve moved for</p><h2>Good moves.<br>Happy customers.</h2></div><a class="text-link" href="{MAP}" target="_blank" rel="noopener">5.0 / 5 Google reviews ↗</a></div><div class="review-grid"><blockquote><span class="stars" aria-label="5 out of 5 stars">★★★★★</span><p>“Friendly delivery people and easy to deal with.”</p><cite>Rebecca Spry <small>Google review · 2024</small></cite></blockquote><blockquote><span class="stars" aria-label="5 out of 5 stars">★★★★★</span><p>“Expert manoeuvring spa removal from a tricky location. Care taken to ensure no damage to property.”</p><cite>Karen Silva <small>Google review excerpt · 2024</small></cite></blockquote><blockquote><span class="stars" aria-label="5 out of 5 stars">★★★★★</span><p>“Prompt and on time, smooth delivery of works would recommend this service”</p><cite>Jeremiah Poljak <small>Google review · 2024</small></cite></blockquote></div><p class="fine">Rating checked 8 November 2026. Read all five reviews on Google.</p></div></section>'''
def quote(service=''):
 options=''.join(f'<option value="{s["name"]}"'+(' selected' if s['name']==service else '')+f'>{s["name"]}</option>' for s in services)
 extra_options=''.join('<option'+(' selected' if x==service else '')+'>'+x+'</option>' for x in ['Retailer partnership','Spa cover enquiry','Other / not sure'])
 return f'''<section class="section quote-section" id="quote"><span id="contact"></span><div class="wrap quote-layout"><div class="quote-intro"><p class="eyebrow">Let’s get it moving</p><h2>A few details.<br>A proper quote.</h2><p>Tell Mark where it’s going and what the access looks like. We’ll confirm the transport plan and price before you book.</p><a class="phone-big" href="tel:+61418329430">0418 329 430 ↗</a><p class="fine">Prefer photos? Attach up to three below.<br>Email is optional. Your phone number is enough.</p><div class="mini-proof"><span>★★★★★</span><p>5.0 from 5 Google reviews</p></div></div><form id="quote-form" class="quote-form"><div class="form-heading"><span>01</span><h3>The move</h3></div><div class="form-grid"><label>Pickup suburb / postcode<input name="pickup" autocomplete="off" maxlength="120" required placeholder="e.g. Croydon 3136"></label><label>Delivery suburb / postcode<input name="delivery" autocomplete="off" maxlength="120" required placeholder="e.g. Geelong 3220"></label><label>What do you need?<select name="service">{options}{extra_options}</select></label><label>Preferred date <span>(optional)</span><input name="date" type="date"></label></div><label>Spa model or size <span>(optional)</span><input name="spa" maxlength="200" placeholder="e.g. 2m square spa, or a model name"></label><label>Anything we should know? <span>(optional)</span><textarea name="message" rows="3" maxlength="2000" placeholder="Gates, steps, fences, sloping access, a private-sale pickup…"></textarea></label><label class="photo-upload">Add access photos <span>(optional · up to 3)</span><input type="file" id="photos" accept="image/*" multiple><small>Choose photos of the spa and access. No photos yet? You can still enquire.</small></label><div id="photo-preview" class="photo-preview" aria-live="polite"></div><div class="form-heading"><span>02</span><h3>Your details</h3></div><div class="form-grid"><label>Your name<input name="name" autocomplete="name" maxlength="100" required></label><label>Phone<input name="phone" type="tel" autocomplete="tel" maxlength="40" required></label></div><label>Email <span>(optional · receive a confirmation)</span><input name="email" type="email" autocomplete="email" maxlength="254"></label><label class="trap" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><label class="consent"><input name="consent" type="checkbox" required><span>Express Spa can contact me about this enquiry. <a href="/privacy">Privacy</a></span></label><input type="hidden" name="estimate" id="estimate-context"><button class="button full" type="submit">Send my quote request <span>↗</span></button><p id="form-status" role="status" aria-live="polite"></p><p class="fine">An enquiry is not a booking. Access, availability and the final price are confirmed with you first.</p></form></div></section>'''
nav='''<a class="skip" href="#main">Skip to content</a><header class="header"><div class="nav-wrap"><a class="logo" href="/" aria-label="Express Spa home"><img src="/images/logo.png" width="185" height="38" alt="Express Spa Deliveries"></a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false">Menu <span>☰</span></button><nav id="navigation" aria-label="Main navigation"><details class="nav-drop"><summary>Services</summary><div>'''+''.join(f'<a href="/{s["slug"]}">{s["name"]}</a>' for s in services)+'''</div></details><a href="/service-areas">Where we go</a><a href="/spa-covers-for-sale">Spa covers</a><a href="/guides">Moving guides</a><a href="/spa-move-estimate">Estimate</a><a href="/contact" class="nav-quote">Get a quote ↗</a></nav></div></header>'''
