est='''<section class="guide-hero"><div class="wrap"><p class="eyebrow">Plan your budget</p><h1>What goes into<br><em>your move?</em></h1><p class="lead">Truck kilometres. Crane lifts. Labour.<br>Start with the details, then get the route and access checked.</p></div></section><section class="section"><div class="wrap estimate-grid"><form id="estimate-form" class="estimate-card"><p class="eyebrow">Your planning inputs</p><h2>Build your estimate.</h2><label>Approximate truck kilometres<input name="km" type="number" min="0" max="5000" value="30" required><small>Planning distance only. Mark confirms the billable route.</small></label><label>Crane lifts<select name="lifts"><option value="0">Not sure / no crane planned</option><option value="1">1 lift</option><option value="2">2 lifts — pickup and delivery</option></select></label><label>Estimated labour hours<input name="hours" type="number" min="0" max="100" step="0.5" value="2" required><small>We confirm the crew and time needed after checking access.</small></label><button class="button full" type="submit">Check my move ↗</button></form><div class="estimate-result" id="estimate-result" role="status" aria-live="polite"><p class="eyebrow">A quote built around the job</p><h2>Three parts.<br>One clear plan.</h2><ol><li><strong>Truck travel</strong><p>The agreed billable kilometres.</p></li><li><strong>Crane lifting</strong><p>The assessed lifts and equipment.</p></li><li><strong>Labour</strong><p>The crew and time needed for your access.</p></li></ol><p class="fine">Send your details for a confirmed price. An estimate is not a booking or a lift assessment.</p></div></div></section>'''
page('spa-move-estimate','Spa move estimate & pricing','Plan a spa move around truck kilometres, crane lifts and labour. Send your route and access photos for a confirmed quote.',est+quote())
