page('spa-covers-for-sale','Genuine Jacuzzi spa covers for sale','Enquire about genuine Jacuzzi spa covers for J210, J115/J215 and J465 models. Confirm current stock, fit, price and pickup with Mark.','<section class="guide-hero"><div class="wrap"><p class="eyebrow">Genuine Jacuzzi covers</p><h1>A better cover.<br><em>Start with the fit.</em></h1><p class="lead">Check the model, measurements and current availability with Mark before travelling.</p></div></section><section class="section"><div class="wrap"><div class="guide-grid">'+''.join(f'<article class="cover-card"><span class="eyebrow">Jacuzzi / {model}</span><div class="cover-shape" aria-hidden="true">{model}</div><h2>{shape}</h2><p>{desc}</p><p class="fine">Current stock, price, pickup location and any delivery costs are confirmed on enquiry.</p><a class="button" href="/contact?service=Spa%20cover%20enquiry&amp;model={model.replace(" / ","-")}">Check this cover ↗</a></article>' for model,shape,desc in covers)+'</div><div class="inline-cta"><h2>Have a photo of your current cover?</h2><p>Send the model, outside measurements and a photo. We’ll help check which option to enquire about. Product photos and fit details are available from Mark.</p><a class="text-link" href="tel:+61418329430">Call 0418 329 430 ↗</a></div></div></section>'+quote('Spa cover enquiry'))
page('retailer-delivery-partners','Spa delivery partners for retailers & manufacturers','Arrange customer deliveries, specialist spa transport and overflow delivery support with Express Spa. Send your routes and spa specifications.',hero('You sell the spa.<br><em>Let’s plan the delivery.</em>','A straightforward way for retailers and manufacturers to arrange customer deliveries, difficult-access assessments and overflow transport.','Retailer delivery partners','hero-trailer')+'<section class="section"><div class="wrap">'+section_blocks([('A useful delivery brief, every time','Send the model, transport dimensions, empty weight, release date, customer suburb and access photos. We can assess the route and equipment before a delivery date is promised.'),('Keep the customer informed','Agree who confirms the access, who handles site preparation and who communicates the delivery window. A clear handover avoids a customer assuming electrical or site works are included.'),('Start with the routes you need','Tell us your common delivery areas, typical spa sizes and where you need extra capacity. We discuss availability and commercial terms directly; there are no public wholesale rates or guaranteed service windows.')])+'</div></section>'+quote('Retailer partnership'))
page('privacy','Privacy & website enquiries','How Express Spa handles information and access photos supplied in a website enquiry.','<section class="guide-hero"><div class="wrap narrow"><p class="eyebrow">Your information</p><h1>Privacy.</h1></div></section><section class="section"><div class="wrap narrow">'+section_blocks([('Information you choose to send','Our quote form collects your name, phone number, pickup and delivery suburbs, optional email, move details and optional access photos. Do not include identity documents, payment details or unnecessary private information in photos.'),('How we use it','We use your details to assess and respond to your enquiry, discuss a quote and arrange a move if you proceed. Submitting an enquiry does not subscribe you to marketing. If you give an email address, we send an acknowledgement.'),('Storage and service providers','Enquiries and access photos are saved in private Vercel storage in Sydney and emailed through Resend to Mark at Express Spa. Email processing may occur outside Australia. We keep enquiries for handling the request and related business records, and review retained information periodically.'),('Access and removal','Contact mark@mrspa.com.au to ask about information you supplied or request correction or deletion. Some records may need to be retained for an agreed job or business recordkeeping. Website enquiries are not published publicly.')])+'</div></section>')
